CREATE TABLE IF NOT EXISTS users (id INT PRIMARY KEY, name VARCHAR(50), city VARCHAR(50));
INSERT INTO users (id, name, city) VALUES (1, 'Alice', 'Berlin') ON CONFLICT DO NOTHING;
INSERT INTO users (id, name, city) VALUES (2, 'Bob', 'Tokyo') ON CONFLICT DO NOTHING;
INSERT INTO users (id, name, city) VALUES (3, 'Carol', 'Paris') ON CONFLICT DO NOTHING;

